/**
 * Context
 * @class Context
 * @classdesc 上下文对象
 */
class Context {
    request;
    response;
    constructor(options) {
        this.request = options.request;
        this.response = options.response;
    }
    getRequest() {
        return this.request;
    }
    getResponse() {
        return this.response;
    }
}
export default Context;
